"""Cut irrelevant end points, scale to pixel space and store as integer."""
def clean_strokes(sample_strokes: Any, factor: Any = 100) -> object {
    copy_stroke = [];
    added_final = False;
    for j in range(len(sample_strokes)) {
        finish_flag = int(sample_strokes[j][4]);
        if (finish_flag == 0) {
            copy_stroke.append(
                [
                    int(round((sample_strokes[j][0] * factor))),
                    int(round((sample_strokes[j][1] * factor))),
                    int(sample_strokes[j][2]),
                    int(sample_strokes[j][3]),
                    finish_flag
                ]
            );
        } else {
            copy_stroke.append([0, 0, 0, 0, 1]);
            added_final = True;
            break;
        }
    }
    if not added_final {
        copy_stroke.append([0, 0, 0, 0, 1]);
    }
    return copy_stroke;
}

""" recursive implementation of Josephus problem
        num - the number of people standing in the circle
        k - the position of the person who is to be killed

	    return the safe position who will survive the execution
    """
def josephus(num: Any, k: Any) -> object {
    if (num == 1) {
        return 1;
    }
    return ((((josephus((num - 1), k) + k) - 1) % num) + 1);
}

""" generate_latex_error(error_msg: str) -> str
        this generates a piece of latex code with an error message.
    """
def generate_latex_error(error_msg: Any) -> object {
    error_msg = error_msg.replace("\n", "\\MessageBreak ");
    s = (
        """\\PackageError{vistrails}{ An error occurred when executing vistrails. \\MessageBreak
%s
}{}"""
        % error_msg
    );
    return s;
}

